BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=public,extensions;
SELECT no_plan();
CREATE FUNCTION pg_temp.poll() RETURNS jsonb LANGUAGE sql AS $$ SELECT public.rdd_planning_read()->'polls'->0 $$;
CREATE FUNCTION pg_temp.option(n integer) RETURNS jsonb LANGUAGE sql AS $$ SELECT value FROM jsonb_array_elements(pg_temp.poll()->'options') WHERE value->>'id'='da000000-0000-4000-8000-'||lpad(n::text,12,'0') $$;
CREATE FUNCTION pg_temp.vote(actor integer,revision integer,responses jsonb,venues jsonb DEFAULT '["da000000-0000-4000-8000-000000000025"]') RETURNS jsonb LANGUAGE sql AS $$
SELECT public.rdd_planning_write(gen_random_uuid(),'vote',jsonb_build_object('actor_id','da000000-0000-4000-8000-'||lpad(actor::text,12,'0'),'poll_id','da000000-0000-4000-8000-000000000010','revision',revision,'options',venues,'date_responses',responses)) $$;
SELECT ok(NOT has_table_privilege('authenticated','rdd_private.planning_ballots','SELECT'),'Raw responses inaccessible');
SELECT ok(NOT has_function_privilege('authenticated','invite_private.rdd_planning_read(integer,integer)','EXECUTE'),'Private read inaccessible');
SELECT ok(NOT has_function_privilege('authenticated','invite_private.rdd_planning_write(uuid,text,jsonb)','EXECUTE'),'Private write inaccessible');
SET LOCAL ROLE anon;
SELECT throws_ok('SELECT public.rdd_planning_read()','42501',null,'Anonymous cannot read');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"da000000-0000-4000-8000-000000000004"}',true);
SELECT throws_ok('SELECT public.rdd_planning_read()','42501',null,'Unadmitted profile denied');
SELECT throws_ok($$SELECT pg_temp.vote(4,0,'{}')$$,'42501',null,'Unadmitted profile cannot vote');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"da000000-0000-4000-8000-000000000003"}',true);
SELECT is(pg_temp.poll()->'date_responses'->>'da000000-0000-4000-8000-000000000021','can','Legacy selected date becomes can attend');
SELECT is(jsonb_object_length_test.count,1,'Unchecked dates not inferred unavailable') FROM (SELECT count(*)::integer FROM jsonb_object_keys(pg_temp.poll()->'date_responses')) jsonb_object_length_test;
SELECT is(pg_temp.poll()->'voters','null'::jsonb,'Member participation count masked');
SELECT is(pg_temp.option(21)->'votes','null'::jsonb,'Date support masked');
SELECT is(pg_temp.option(25)->'votes','null'::jsonb,'Venue count masked');
SELECT is(pg_temp.option(21)->'availability','null'::jsonb,'All date aggregates masked');
SELECT is(pg_temp.poll()->'pairs','[]'::jsonb,'Pair results masked');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"da000000-0000-4000-8000-000000000002"}',true);
SELECT lives_ok($$SELECT pg_temp.vote(2,0,'{"da000000-0000-4000-8000-000000000021":"preferred","da000000-0000-4000-8000-000000000022":"can","da000000-0000-4000-8000-000000000023":"cannot","da000000-0000-4000-8000-000000000024":"maybe"}')$$,'All four responses accepted with venue checkbox');
SELECT is(jsonb_array_length(pg_temp.poll()->'mine'),3,'Only positive dates and venue count as support');
SELECT is(pg_temp.poll()->'date_responses'->>'da000000-0000-4000-8000-000000000023','cannot','Own unavailable response returned');
SELECT throws_ok($$SELECT pg_temp.vote(2,0,'{}')$$,'40001',null,'Stale ballot rejected');
SELECT throws_ok($$SELECT pg_temp.vote(2,1,'[]')$$,'22023',null,'Invalid response container rejected');
SELECT throws_ok($$SELECT pg_temp.vote(2,1,'{"da000000-0000-4000-8000-000000000021":"yes"}')$$,'22023',null,'Unknown state rejected');
SELECT throws_ok($$SELECT pg_temp.vote(2,1,'{"da000000-0000-4000-8000-000000000021":null}')$$,'22023',null,'Null state rejected');
SELECT throws_ok($$SELECT pg_temp.vote(2,1,'{"da000000-0000-4000-8000-000000000025":"can"}')$$,'40001',null,'Venue cannot receive date response');
SELECT throws_ok($$SELECT pg_temp.vote(2,1,'{"da000000-0000-4000-8000-000000000099":"can"}')$$,'40001',null,'Foreign or missing option rejected');
SELECT throws_ok($$SELECT pg_temp.vote(2,1,'{}','["da000000-0000-4000-8000-000000000021"]')$$,'40001',null,'New ballot cannot use date checkboxes');
SELECT throws_ok($$SELECT pg_temp.vote(1,1,'{}')$$,'42501',null,'Actor cannot be forged');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"da000000-0000-4000-8000-000000000001"}',true);
SELECT is((pg_temp.option(21)->'availability'->>'can')::integer,2,'Preferred included in attendance');
SELECT is((pg_temp.option(21)->'availability'->>'preferred')::integer,1,'Preference counted separately');
SELECT is((pg_temp.option(23)->'availability'->>'cannot')::integer,1,'Unavailable counted');
SELECT is((pg_temp.option(24)->'availability'->>'maybe')::integer,1,'Maybe counted');
SELECT is((pg_temp.option(23)->'availability'->>'unknown')::integer,1,'Unanswered retained among respondents');
SELECT is((pg_temp.option(25)->>'votes')::integer,2,'Venue behavior unchanged');
SELECT is((pg_temp.poll()->'pairs'->0->>'support')::integer,2,'Overlap includes can and preferred only');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"da000000-0000-4000-8000-000000000002"}',true);
-- Old clients preserve choices they cannot express, including preferred.
SELECT lives_ok($$SELECT public.rdd_planning_write(gen_random_uuid(),'vote','{"actor_id":"da000000-0000-4000-8000-000000000002","poll_id":"da000000-0000-4000-8000-000000000010","revision":1,"options":["da000000-0000-4000-8000-000000000021","da000000-0000-4000-8000-000000000022","da000000-0000-4000-8000-000000000025"]}')$$,'Legacy ballot still saves');
SELECT is(pg_temp.poll()->'date_responses'->>'da000000-0000-4000-8000-000000000021','preferred','Legacy client preserves preference');
SELECT is(pg_temp.poll()->'date_responses'->>'da000000-0000-4000-8000-000000000023','cannot','Legacy client preserves unavailable');
SELECT lives_ok($$SELECT pg_temp.vote(2,2,'{}','[]')$$,'Responses can be cleared');
SELECT is(pg_temp.poll()->'date_responses','{}'::jsonb,'Clear means unknown, not unavailable');
-- Stable request replay, even after closure.
SELECT public.rdd_planning_write('da000000-0000-4000-8000-000000000090','vote','{"actor_id":"da000000-0000-4000-8000-000000000002","poll_id":"da000000-0000-4000-8000-000000000010","revision":3,"options":[],"date_responses":{"DA000000-0000-4000-8000-000000000022":"preferred"}}');
SELECT is(pg_temp.poll()->'date_responses'->>'da000000-0000-4000-8000-000000000022','preferred','UUID keys canonicalized');
SELECT is((public.rdd_planning_write('da000000-0000-4000-8000-000000000090','vote','{"actor_id":"da000000-0000-4000-8000-000000000002","poll_id":"da000000-0000-4000-8000-000000000010","revision":3,"options":[],"date_responses":{"DA000000-0000-4000-8000-000000000022":"preferred"}}')->>'replayed')::boolean,true,'Identical request replays');
SELECT throws_ok($$SELECT pg_temp.vote(2,4,'{"DA000000-0000-4000-8000-000000000022":"can","da000000-0000-4000-8000-000000000022":"cannot"}')$$,'22023',null,'Aliased duplicate dates rejected');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"da000000-0000-4000-8000-000000000001"}',true);
SELECT public.rdd_planning_write(gen_random_uuid(),'close_poll','{"actor_id":"da000000-0000-4000-8000-000000000001","poll_id":"da000000-0000-4000-8000-000000000010","revision":1}');
SELECT throws_ok($$SELECT public.rdd_planning_write(gen_random_uuid(),'schedule','{"actor_id":"da000000-0000-4000-8000-000000000001","poll_id":"da000000-0000-4000-8000-000000000010","title":"Example night","date_option":"da000000-0000-4000-8000-000000000021","venue_option":"da000000-0000-4000-8000-000000000025"}')$$,'22023',null,'Equal attendance with lower preference needs organizer reason');
SELECT lives_ok($$SELECT public.rdd_planning_write(gen_random_uuid(),'schedule','{"actor_id":"da000000-0000-4000-8000-000000000001","poll_id":"da000000-0000-4000-8000-000000000010","title":"Example night","date_option":"da000000-0000-4000-8000-000000000022","venue_option":"da000000-0000-4000-8000-000000000025"}')$$,'Best attendance/preference schedules without override');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"da000000-0000-4000-8000-000000000002"}',true);
SELECT is((pg_temp.poll()->>'voters')::integer,2,'Closed participation totals revealed');
SELECT is((pg_temp.option(21)->>'votes')::integer,1,'Closed date attendance revealed');
SELECT is((pg_temp.option(25)->>'votes')::integer,1,'Closed venue votes revealed');
SELECT is((pg_temp.option(22)->'availability'->>'preferred')::integer,1,'Closed availability revealed');
SELECT throws_ok($$SELECT pg_temp.vote(2,4,'{}')$$,'PT410',null,'Closed poll rejects responses');
SELECT * FROM finish();
ROLLBACK;
